#define SURF_DIST .0001
#define EPS .0001
#define PI 3.14
#define PI2 6.28
#define saturate(a) clamp(a,0.,1.)

// https://iquilezles.org/articles/palettes/
vec3 palette(float t)
{
    vec3 a = vec3(.1, .3, .8);
    vec3 b = vec3(.8, .4, .1);
    vec3 c = vec3(.4, .8, .9);
    vec3 d = vec3(.2, .9, .6);
    return a + b*cos( 6.283185*(c*t+d) );
}

// NOTE: I realized later that there was a bug, but I'll leave it at that...
mat2 rotate(float a) {
    float s = sin(a), c = cos(a);
    return mat2(c, s, -s, c);
}

vec2 pmod(vec2 p, float s) {
    float a = PI / s - atan(p.x, p.y);
    float n = PI2 / s;
    a = floor(a / n) * n;
    p *= rotate(a);
    return p;
}

float sdBox(vec3 p, vec3 b) {
    vec3 q = abs(p) - b;
    return length(max(q, 0.)) + min(max(q.x, max(q.y, q.z)), 0.);
}

float scene(vec3 p) {
    float d = 100000.;
    float t = iTime;

    p.xy *= rotate(sin(p.z * 1.2) * sin(p.z * 1.2) + t * .22);

    p.y += sin(t * .5) * .045;
    p.z += t * .6;
    p.xy = pmod(p.xy, 6.);

    p.y -= -2. + sin(p.z) * .05;

    vec3 rep = vec3(3., 3., .55);

    p = mod(p, rep) - rep / 2.;

    d = min(d, sdBox(p - vec3(0., .2, 0.), vec3(1.35, 1.35, 2.)));

    for(float i = 0.; i < 4.; i++) {
        vec3 q = p;
        q.y -= (i + 1.) * .11;

        d = min(d, sdBox(q, vec3(2., .06, .025)));
        d = max(d, -sdBox(q - vec3(0., .4, 0.), vec3(2., .05, .5)));
        d = max(d, -sdBox(q - vec3(1., .4, 1.), vec3(2., .1, .5)));
        d = max(d, -sdBox(q - vec3(1., .4, -1.), vec3(2., .1, .5)));

        p = q;
    }

    return d;
}

vec3 getNormal(vec3 p) {
    vec2 e = vec2(EPS, 0);
    return normalize(
    	vec3(
            scene(p + e.xyy) - scene(p - e.xyy),
            scene(p + e.yxy) - scene(p - e.yxy),
            scene(p + e.yyx) - scene(p - e.yyx)
        )
    );
}

vec3 raymarch(vec3 ro, vec3 rd) {
    float accDist = 0.;    
    float scan = 0.;
    float emissive = 0.;


    // base: https://www.shadertoy.com/view/MtScWW
    for(int i = 0; i < 99; i++) {
        vec3 p = ro + rd * accDist;
        float dist = scene(p);
        dist = max(abs(dist), .004);
        scan += exp(dist * -30.);
        if(dist >= SURF_DIST) {     
            emissive += exp(abs(dist) * -200.);
        }
        accDist += dist * .3;                
    }

    return vec3(accDist, scan, emissive);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    float t = iTime;

    vec2 uv = (fragCoord.xy * 2. - iResolution.xy) / min(iResolution.x, iResolution.y);

    uv *= rotate(sin(t * .05) * .1);

    float phi = sin(t * .45) * .05 - PI / 2.;
    float radius = .002;
    vec3 ro = vec3(
        cos(phi) * radius,
        0.,
        sin(phi) * radius
    );
    vec3 lookat = vec3(0.);
    vec3 forward = normalize(lookat - ro);
    vec3 right = normalize(cross(vec3(0., 1., 0.), forward));
    vec3 up = normalize(cross(forward, right));

    float zoom = 2.5;
    vec3 rd = normalize(right * uv.x + up * uv.y + forward * zoom);

    vec3 result = raymarch(ro, rd);
    float dist = result.x;

    vec3 col = vec3(0.);

    vec3 p = ro + rd * dist;
    vec3 lightDir = normalize(vec3(1., 1., -1.));

    // cheap diffuse and normal because always not hit surface
    vec3 normal = getNormal(p);    
    float diffuse = dot(lightDir, normal) * .5 + .5;

    float scan = max(0., result.y);    
    float emissive = result.z;

    vec3 emissiveColor = palette(p.z);

    col = vec3(
        diffuse * .05
        + scan * .035
        + emissive * (.001 + (sin(abs(p.z * 10.) * 1. + t * 3.) * .2 + .8) * .025) * mix(emissiveColor, normal, .05)
    ) * exp(-.9 * dist);

    col = pow(col, vec3(.45450));

    fragColor = vec4(col, 1.);
}
